5	import '../../domain/entities/export_job_state.dart';
6	import '../../domain/repositories/export_repository.dart';
7	
8	/// Drives `ExportStatusSheet` (spec-7-1) — a fresh, `get_it`-factory-
9	/// scoped instance per download-icon tap (Code Map: the `registerFactory`
10	/// one-shot-cubit precedent set by `TextEntryCubit`), closed by the call
11	/// site itself once done with it (`MeusRegistrosScreen`'s own export handler/
12	/// `ExportStatusSheet.show()`, mirroring `InsertionModal.show()`'s own
13	/// cubit-disposal convention), never by a `get_it` `dispose:` hook.
14	///
15	/// Starts in [ExportJobState.preparing] — the same visual the
16	/// `export-summary-create` 202 response's own `status: 'pending'` always
17	/// implies (`openapi.yaml`), so no separate "creating..." state is needed
18	/// before [start]'s own `createJob` call resolves.
19	class ExportJobCubit extends Cubit<ExportJobState> {
20	  ExportJobCubit(this._repository) : super(const ExportJobState.preparing());
21	
22	  final ExportRepository _repository;
23	
24	  /// Design Notes — fixed poll cadence (docs/input is silent on this):
25	  /// the server job always reaches a terminal state, so no client
26	  /// timeout exists either.
27	  static const _pollInterval = Duration(seconds: 2);
28	
29	  String? _jobId;
30	  Timer? _pollTimer;
31	
32	  /// Creates the export job for [periodStart]/[periodEnd]
33	  /// (`export-summary-create`) and, on success, starts this cubit's own
34	  /// `Timer.periodic` poll loop against `export-status-get`.
35	  ///
36	  /// Returns `false` on a create failure (Boundaries: "Create fails →
37	  /// inline error, sheet never opens") — the same failure is also
38	  /// emitted as [ExportJobState.error] so the caller can read [state] for
39	  /// [Failure.message] without this method also having to hand back the
40	  /// raw `Failure` itself (the `Either<Failure, T>` shape, RNF09, is the
41	  /// repository's own contract, not every cubit method's).
42	  Future<bool> start({
43	    required DateTime periodStart,
44	    required DateTime periodEnd,
45	  }) async {
46	    final result = await _repository.createJob(
47	      periodStart: periodStart,
48	      periodEnd: periodEnd,
49	    );
50	    if (isClosed) {
51	      return false;
52	    }
53	    return result.match(
54	      (failure) {
55	        emit(ExportJobState.error(failure));
56	        return false;
57	      },
58	      (jobId) {
59	        _jobId = jobId;
60	        _startPolling();
61	        return true;
62	      },
63	    );
64	  }
65	
66	  void _startPolling() {
67	    _pollTimer?.cancel();
68	    _pollTimer = Timer.periodic(_pollInterval, (_) => _poll());
69	  }
70	
71	  Future<void> _poll() async {
72	    final jobId = _jobId;
73	    if (jobId == null) {
74	      return;
75	    }
76	    final result = await _repository.getStatus(jobId);
77	    if (isClosed) {
78	      return;
79	    }
80	    result.match(
81	      (_) {
82	        // A transient poll failure (docs/input is silent on this) is
83	        // swallowed rather than surfaced, so one flaky network blip
84	        // never flips a still-running job to a false terminal error —
