    'the narrative, never the whole job',
    (tester) async {
      repository.getStatusResults.add(
        right(const ExportJobState.done(ExportOutcome.narrativeUnavailable)),
      );
      await cubit.start(
        periodStart: DateTime(2026, 1, 1),
        periodEnd: DateTime(2026, 1, 31),
      );
      await _pumpSheet(tester, cubit);
      await _advancePastOnePoll(tester);

      expect(find.text('Baixar PDF'), findsNothing);
      expect(find.text('Baixar dados brutos'), findsOneWidget);
      expect(
        find.textContaining('a narrativa falhou'),
        findsOneWidget,
      );
    },
  );

  testWidgets(
    'Erro: generic error copy, no download button offered',
    (tester) async {
      repository.getStatusResults.add(
        right(
          const ExportJobState.error(
            Failure.aiGenerationTimeout(message: 'boom'),
          ),
        ),
      );
      await cubit.start(
        periodStart: DateTime(2026, 1, 1),
        periodEnd: DateTime(2026, 1, 31),
      );
      await _pumpSheet(tester, cubit);
      await _advancePastOnePoll(tester);

      expect(
        find.text('Não foi possível gerar a exportação.'),
        findsOneWidget,
      );
      expect(find.text('Baixar PDF'), findsNothing);
      expect(find.text('Baixar dados brutos'), findsNothing);
    },
  );

  testWidgets(
    'Período vazio: adjust-period copy, no download button offered',
    (tester) async {
      repository.getStatusResults.add(
        right(const ExportJobState.emptyPeriod()),
      );
